import{_ as s,c as t,o,a3 as i}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"macOS の権限","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/permissions.md","filePath":"ja/guide/permissions.md","lastUpdated":1787284674000}'),e={name:"ja/guide/permissions.md"};function r(n,a,l,p,h,c){return o(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="macos-の権限" tabindex="-1">macOS の権限 <a class="header-anchor" href="#macos-の権限" aria-label="Permalink to &quot;macOS の権限&quot;">​</a></h1><p>ClipboxAI は、最高の体験を提供するためにいくつかの macOS 権限を求める場合があります。このページでは、各権限の目的と管理方法を説明します。</p><h2 id="クリップボード-オートメーション" tabindex="-1">クリップボード / オートメーション <a class="header-anchor" href="#クリップボード-オートメーション" aria-label="Permalink to &quot;クリップボード / オートメーション&quot;">​</a></h2><p>バックグラウンドでクリップボードをキャプチャし、結果をペーストボードへ書き戻すために、ClipboxAI は macOS のオートメーション（Automation）アクセスを使用します。</p><p><strong>用途</strong>: コピー時に現在のペーストボードを読み取り、アクション実行時に結果を書き戻すこと。</p><p><strong>管理</strong>: <strong>システム設定 → プライバシーとセキュリティ → オートメーション</strong> → <strong>ClipboxAI</strong> を有効にします。</p><p>初回起動時に求められたタイミングでアクセスを許可してください。いつでも管理や取り消しが可能です。</p><h2 id="アクセシビリティ-任意" tabindex="-1">アクセシビリティ（任意） <a class="header-anchor" href="#アクセシビリティ-任意" aria-label="Permalink to &quot;アクセシビリティ（任意）&quot;">​</a></h2><p>一部のビルドでは、グローバルなキーボードショートカットの提供や、どこからでも履歴パネルを呼び出すためにアクセシビリティを使用します。</p><p><strong>用途</strong>: アプリがフォーカスされていないときでも、履歴パネルを開いたりホットキーでアクションを実行したりすること。</p><p><strong>管理</strong>: <strong>システム設定 → プライバシーとセキュリティ → アクセシビリティ</strong> → <strong>ClipboxAI</strong> を有効にします。</p><h2 id="通知-任意" tabindex="-1">通知（任意） <a class="header-anchor" href="#通知-任意" aria-label="Permalink to &quot;通知（任意）&quot;">​</a></h2><p>ClipboxAI は、時間のかかるアクションが完了したときや注意が必要なときに、通知を表示する場合があります。</p><p><strong>用途</strong>: アクションの完了時や設定が必要なときにお知らせすること。</p><p><strong>管理</strong>: <strong>システム設定 → 通知</strong> → <strong>ClipboxAI</strong>。</p><h2 id="フルディスクアクセス-任意" tabindex="-1">フルディスクアクセス（任意） <a class="header-anchor" href="#フルディスクアクセス-任意" aria-label="Permalink to &quot;フルディスクアクセス（任意）&quot;">​</a></h2><p>通常の利用には不要です。システムで保護された場所からクリップを読み取らせたい場合にのみ必要です。</p><p><strong>管理</strong>: <strong>システム設定 → プライバシーとセキュリティ → フルディスクアクセス</strong>。</p><p>この権限は任意であり、高度なシナリオでのみ必要になります。</p><h2 id="ターミナルでの権限リセット" tabindex="-1">ターミナルでの権限リセット <a class="header-anchor" href="#ターミナルでの権限リセット" aria-label="Permalink to &quot;ターミナルでの権限リセット&quot;">​</a></h2><p>権限ダイアログが閉じられた、あるいは状態が不整合になった場合は、<code>tccutil</code> を使って macOS の権限プロンプトをリセットできます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ClipboxAI のオートメーション/アクセシビリティのプロンプトをリセット</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p><code>tccutil</code> の実行後、アプリを再起動し、再度その機能を呼び出すと再びプロンプトが表示されます。</p><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h2><ul><li>クリップボード履歴にコピーが記録されない場合は、<strong>オートメーション</strong> 権限が付与されているか確認してください。</li><li>グローバルショートカットが機能しない場合は、<strong>アクセシビリティ</strong> 権限を確認してください。</li><li>権限を変更した後は、必ず ClipboxAI を終了して再度開き、変更を反映させてください。</li></ul><p>さらに詳しいヘルプについては、<a href="/ja/guide/troubleshooting.html">トラブルシューティングガイド</a>を参照してください。</p>`,26)])])}const u=s(e,[["render",r]]);export{g as __pageData,u as default};
